  const workers=[];globalThis.Worker=class {onmessage=null;onerror=null;messages=[];terminated=false;constructor(){workers.push(this)}postMessage(job){this.messages.push(job)}terminate(){this.terminated=true}};
  try{const source='**one**\n'+'plain text\n'.repeat(1300);make(source);await wait(190);workers[0].onerror();await wait(190);workers[1].onerror();await wait(190);assert.match(document.querySelector('.cm-lp-preview-status').textContent,/暂不可后台预览/);assert.equal(document.querySelector('.cm-lp-strong'),null);view.dispatch({changes:{from:source.length,insert:'中文'}});await wait(190);assert.equal(view.state.doc.toString(),source+'中文');assert.equal(workers.length,2);assert.equal(changed,1)}finally{delete globalThis.Worker}
