 if(process.env.LR_ORIGINAL_MD) await t.test('owner original uses production Worker model and retains exact first/last source across mode and undo',async()=>{
  const {readFileSync,readdirSync}=require('node:fs'),vm=require('node:vm'),{createHash}=require('node:crypto');
  const source=readFileSync(process.env.LR_ORIGINAL_MD,'utf8'),hash=s=>createHash('sha256').update(s).digest('hex'),before=hash(source);
  const artifact=readdirSync(join(root,'dist/assets')).find(name=>/^markdownPreview\.worker-.*\.js$/.test(name));assert.ok(artifact);const code=readFileSync(join(root,'dist/assets',artifact),'utf8');let retired=false;
  globalThis.Worker=class {onmessage=null;onerror=null;terminated=false;constructor(){const self={postMessage:data=>{if(!this.terminated)this.onmessage?.({data})}};this.context={self,URL,URLSearchParams,TextEncoder,TextDecoder};vm.createContext(this.context);vm.runInContext(code,this.context,{timeout:5000})}postMessage(data){setTimeout(()=>{if(!this.terminated)this.context.self.onmessage({data})},0)}terminate(){this.terminated=true;retired=true}};
  try{const options=make(source);await wait(230);assert.ok(document.querySelector('.cm-lp-h1'));assert.equal(hash(view.state.doc.toString()),before);assert.equal(changed,0);view.dispatch({effects:mode.reconfigure([])});assert.equal(view.state.doc.toString(),source);view.dispatch({effects:mode.reconfigure(cmLivePreview(options))});await wait(230);assert.ok(document.querySelector('.cm-lp-h1'));assert.equal(view.state.doc.toString(),source);view.dispatch({changes:{from:source.length,insert:'临时校验'}});assert.equal(undo(view),true);assert.equal(hash(view.state.doc.toString()),before);assert.equal(hash(readFileSync(process.env.LR_ORIGINAL_MD,'utf8')),before);assert.equal(retired,true)}finally{delete globalThis.Worker}
 });
